SELECT F.A_STOCKSNAME AS `股票简称`, F.A_STOCKCODE AS `股票代码`, DATE_FORMAT(F.ENDDATE, '%Y-%m-%d') AS `报告期截止日期`, DATE_FORMAT(F.DECLAREDATE, '%Y-%m-%d') AS `业绩预告发布日期`, ROUND(F.MIN_VAL, 1) AS `预计净利润下限(万)`, ROUND(F.MAX_VAL, 1) AS `预计净利润上限(万)` FROM STK_ACHIEVE_FORECAST F WHERE F.A_STOCKSNAME LIKE '%紫金矿业%' AND F.ISVALID = 1 AND F.ENDDATE = '2025-06-30' ORDER BY F.DECLAREDATE DESC LIMIT 1;
